package com.englishhero.practice;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
import com.englishhero.identity.*;
import com.englishhero.reading.*;
import com.englishhero.web.BusinessException;
import static com.englishhero.practice.PracticeDtos.*;
@Service
@Transactional(readOnly=true)
public class PracticeCatalogService {
 private final PracticeSubjectiveAdminService subjective;private final PracticeSetMapper sets;private final PracticeQuizMapper quizzes;private final ArticleMapper articles;private final AdminArticleService articleDtos;private final IdentityService identities;private final ObjectMapper json;
 public PracticeCatalogService(PracticeSetMapper sets,PracticeQuizMapper quizzes,ArticleMapper articles,AdminArticleService articleDtos,IdentityService identities,ObjectMapper json,PracticeSubjectiveAdminService subjective){this.subjective=subjective;this.sets=sets;this.quizzes=quizzes;this.articles=articles;this.articleDtos=articleDtos;this.identities=identities;this.json=json;}
 public Map<String,Object> catalog(){var exams=new ArrayList<Map<String,Object>>();for(String code:List.of("CET4","CET6","POSTGRAD1","POSTGRAD2")){String label=switch(code){case"CET4"->"四级";case"CET6"->"六级";case"POSTGRAD1"->"考研英语一";default->"考研英语二";};var types=new ArrayList<Map<String,Object>>();types.add(Map.of("code","DETAILED","label",code.startsWith("CET")?"仔细阅读":"阅读理解","available",code.equals("CET4")));for(String type:code.startsWith("CET")?List.of("CLOZE","MATCH"):List.of("NEW"))types.add(Map.of("code",type,"label",type.equals("CLOZE")?"选词填空":type.equals("MATCH")?"长篇匹配":"新题型","available",(type.equals("CLOZE")||type.equals("MATCH"))&&code.equals("CET4")));types.add(Map.of("code","LISTENING","label","整套听力","available",code.equals("CET4")));for(String type:List.of("WRITING","TRANSLATION"))types.add(Map.of("code",type,"label",type.equals("WRITING")?"写作":"翻译","available",code.equals("CET4")));exams.add(Map.of("code",code,"label",label,"available",code.equals("CET4"),"types",types));}return Map.of("exams",exams);}
 private Long user(SessionPrincipal actor,Query query){if(actor==null){if(query.state()!=null&&!query.state().isBlank()&&!query.state().equals("ALL"))throw new BusinessException(401,"UNAUTHENTICATED","登录后可查看本人练习状态");return null;}identities.current(actor);return actor.userId();}
 public ReadingDtos.PageDto<SetSummary> list(SessionPrincipal actor,Query query){Long user=user(actor,query);return new ReadingDtos.PageDto<>(sets.list(query,false,user).stream().map(r->summary(r,user)).toList(),query.page(),query.pageSize(),sets.count(query,false,user));}
 public Map<String,Object> facets(SessionPrincipal actor,Query query){Long user=user(actor,query);var result=new LinkedHashMap<String,Object>();for(String field:List.of("source","readingType","topic","year","month","paperNo"))result.put(field,sets.facet(query,user,field));result.put("state",user==null?List.of():sets.facet(query,user,"state"));return result;}
 public SetDetail detail(SessionPrincipal actor,String id){if(actor!=null)identities.current(actor);var r=sets.get(ArticleRules.id(id,"setId"),false);if(r==null||r.publishedVersionId()==null||!r.status().equals("PUBLISHED"))throw PracticeAdminService.missing();var article=articles.article(r.articleId(),false);if(article==null)throw PracticeAdminService.missing();var s=summary(r,actor==null?null:actor.userId());var v=sets.version(r.publishedVersionId());if(PracticeSubjectiveRules.isSubjective(v.readingType()))return new SetDetail(s.id(),s.setVersionId(),s.metadata(),s.examCode(),v.readingType(),1,s.publishedAt(),s.personalState(),s.currentAttemptId(),null,List.of(),subjective.content(v.id(),true).publicPrompt());return new SetDetail(s.id(),s.setVersionId(),s.metadata(),s.examCode(),v.readingType(),s.questionCount(),s.publishedAt(),s.personalState(),s.currentAttemptId(),"LISTENING".equals(v.readingType())?null:articleDtos.version(v.articleId(),v.articleVersionId()),wordBank(v.wordBankJson()));}
 private SetSummary summary(PracticeSetMapper.Row r,Long user){var v=sets.version(r.publishedVersionId());return new SetSummary(""+r.id(),""+v.id(),json.readValue(v.metadata(),Metadata.class),r.exam(),r.readingType(),PracticeSubjectiveRules.isSubjective(v.readingType())?1:quizzes.published(v.quizVersionId()).size(),v.publishedAt(),sets.state(r.id(),user),sets.current(r.id(),user));}
 private List<String> wordBank(String value){return value==null?List.of():List.of(json.readValue(value,String[].class));}
}
